import{_ as e}from"./chunks/popup-network.DtVnjL4E.js";import{_ as o,o as r,c as t,a2 as s}from"./chunks/framework.CfwCq2QB.js";const u=JSON.parse('{"title":"CORS 调试","description":"","frontmatter":{},"headers":[],"relativePath":"features/cors.md","filePath":"features/cors.md"}'),i={name:"features/cors.md"};function l(c,a,n,d,h,_){return r(),t("div",null,[...a[0]||(a[0]=[s('<h1 id="cors-调试" tabindex="-1">CORS 调试 <a class="header-anchor" href="#cors-调试" aria-label="Permalink to &quot;CORS 调试&quot;">​</a></h1><p>一句话：可开关地为网页的 XHR / fetch 响应补充跨域响应头，方便本地联调。</p><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><p>本地开发时最常见的报错：前端 <code>localhost:5173</code> 直接请求另一个域名的接口，浏览器因为缺少 <code>Access-Control-Allow-Origin</code> 响应头把结果拦下来——接口明明通了，页面里就是读不到。</p><p>开这个开关后，DevGo 为网页的 XHR / fetch 响应补充跨域响应头，请求正常返回，前端不用改代码、不用配代理，先把逻辑调通。</p><h2 id="怎么开" tabindex="-1">怎么开 <a class="header-anchor" href="#怎么开" aria-label="Permalink to &quot;怎么开&quot;">​</a></h2><p>弹窗「网络」页 →「解除 CORS 限制」开关。开关切换后<strong>刷新页面</strong>生效。</p><img src="'+e+'" alt="弹窗网络页"><h2 id="边界与注意" tabindex="-1">边界与注意 <a class="header-anchor" href="#边界与注意" aria-label="Permalink to &quot;边界与注意&quot;">​</a></h2><ul><li>仅用于<strong>本地开发调试</strong>，别长期开着逛网页：它削弱的是浏览器的同源防护</li><li>救不了这些情况：服务器直接拒绝 OPTIONS 预检、需要携带凭证（Cookie）的请求、CSP 限制、混合内容（HTTPS 页面请求 HTTP 接口）——这些得从服务端或页面本身解决</li><li>与真实 IP 防护、代理模式互不影响，可以同时使用</li></ul>',10)])])}const m=o(i,[["render",l]]);export{u as __pageData,m as default};
